package main
import("fmt";"os";"github.com/minz/minzc/pkg/z80asm";"github.com/minz/minzc/pkg/emulator")
func main(){s,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};a,e:=z80asm.NewAssembler().AssembleString("ORG 0x8000\n"+string(s));if e!=nil||len(a.Errors)>0{panic(fmt.Sprint(e,a.Errors))};for _,p:=range []struct{x,y,v byte}{{0,0,7},{3,2,9},{4,4,255}}{z:=emulator.NewRemogattoZ80();z.LoadMemory(uint16(a.Origin),a.Binary);board:=uint16(a.Symbols["board"]);for i:=0;i<25;i++{z.LoadMemory(board+uint16(i),[]byte{byte(i+40)})};call:=func(name string,r emulator.Registers) emulator.Registers{z.LoadMemory(0xeffe,[]byte{0,0xf1});r.PC=uint16(a.Symbols[name]);r.SP=0xeffe;z.SetRegisters(r);for i:=0;i<2000&&z.GetRegisters().PC!=0xf100;i++{z.Step()};return z.GetRegisters()};r:=call("board_set",emulator.Registers{A:p.x,BC:uint16(p.v)<<8|uint16(p.y)});fmt.Printf("set(%d,%d,%d) PC=%04x SP=%04x\n",p.x,p.y,p.v,r.PC,r.SP);r=call("board_get",emulator.Registers{A:p.x,BC:uint16(p.y)});fmt.Printf("get A=%d want=%d PC=%04x SP=%04x\n",r.A,p.v,r.PC,r.SP)}}
